(record_service_outputs.py). Live-model tests request `ensure_ollama_model_available`, which —
like mcp-agent's (docs/phase6/decisions.md H50) — hard-fails rather than skipping when Ollama
isn't reachable.
"""
from __future__ import annotations

import copy
import json
import os
from pathlib import Path
from types import SimpleNamespace

import httpx
import pytest

from outcome_prediction_agent.service import ToolRefused

FIXTURES = Path(__file__).parent / "fixtures"
OUTPUTS = json.loads((FIXTURES / "service_outputs.json").read_text())
TOOLS = json.loads((FIXTURES / "service_tools.json").read_text())
PATIENT = OUTPUTS["patient_id"]


class FakeService:
    """Answers like the scoring service, from its recorded outputs. Enforces the same schemas."""

    def __init__(self, unavailable: bool = False):
        self.calls: list[tuple[str, dict]] = []
        self.unavailable = unavailable

    def definitions(self) -> list[dict]:
        from outcome_prediction_agent.service import ServiceUnavailable
        if self.unavailable:
            raise ServiceUnavailable("down")
        return copy.deepcopy(TOOLS)

    def call(self, name: str, args: dict) -> dict:
        self.calls.append((name, args))
        schema = next((t["input_schema"] for t in TOOLS if t["name"] == name), None)
        if schema is None:
            raise ToolRefused(f"no tool {name!r}")
        if extra := set(args) - set(schema["properties"]):
            raise ToolRefused(f"extra inputs are not permitted ({sorted(extra)})")
        if name == "get_model_card":
            return copy.deepcopy(OUTPUTS["model_card"])
        if name == "find_patient":
            key = {"Jane Doe": "one_match", "Doe": "two_matches"}.get(args.get("name", "").strip(), "no_match")
            return copy.deepcopy(OUTPUTS[key])
        if args.get("as_of") == "1950-01-01":
            return copy.deepcopy(OUTPUTS["no_estimate"])
        if args.get("patient_id") in (PATIENT, "9999"):
            return copy.deepcopy(OUTPUTS["estimate"])
        return {"outcome": "not_found", "detail": "patient not found"}


def tool_use(name: str, args: dict, id_: str = "t1"):
    return SimpleNamespace(type="tool_use", name=name, input=args, id=id_)


def text(content: str):
    return SimpleNamespace(type="text", text=content)


class ScriptedModel:
    """A stand-in for the LLM client: returns the given responses in order (then plain text)."""

    def __init__(self, *turns):
        self.turns = list(turns)
        self.requests: list[dict] = []
        self.messages = self

    def create(self, **kwargs):
        self.requests.append(kwargs)
        content = self.turns.pop(0) if self.turns else [text("I think it's about 40%, which is high risk.")]
        has_tool = any(getattr(b, "type", "") == "tool_use" for b in content)
        return SimpleNamespace(content=content, stop_reason="tool_use" if has_tool else "end_turn", usage=None)


@pytest.fixture
def service() -> FakeService:
    return FakeService()


OLLAMA_HOST = os.environ.get("OLLAMA_HOST", "http://localhost:11434")
OLLAMA_MODEL = os.environ.get("OLLAMA_MODEL", "llama3.2:1b")


@pytest.fixture(scope="session")
def ensure_ollama_model_available() -> None:
    try:
        names = {m["name"] for m in httpx.get(f"{OLLAMA_HOST}/api/tags", timeout=5.0).json().get("models", [])}
        if OLLAMA_MODEL not in names:
            with httpx.stream("POST", f"{OLLAMA_HOST}/api/pull", json={"name": OLLAMA_MODEL}, timeout=300.0) as r:
                r.raise_for_status()
                for _ in r.iter_lines():
